// The yak on the pages where something is wrong (card 672): lost (404), broken (an error), offline (no connection).
// Inline SVG generated by scripts/logo/mascot.py — ink = currentColor, accent = var(--accent); reduced motion → still.
import type { ReactNode } from "react";
import { YAK_MASCOTS } from "./yakMascots";

export type MascotScene = keyof typeof YAK_MASCOTS;

// size: page = a whole page's state (404, a crash); card = a failed read inside a page; banner = the down banner
export function Mascot({
  scene,
  title,
  children,
  size = "page",
}: {
  scene: MascotScene;
  title: ReactNode;
  children?: ReactNode;
  size?: "page" | "card" | "banner";
}) {
  const Heading = size === "page" ? "h1" : "strong";
  return (
    <div className={`mascot mascot-${size}`} data-scene={scene}>
      <span className="mascot-art" aria-hidden="true" dangerouslySetInnerHTML={{ __html: YAK_MASCOTS[scene] }} />
      <div className="mascot-text">
        <Heading className="mascot-title">{title}</Heading>
        {children}
      </div>
    </div>
  );
}
